{"command": "python3 << 'PYEOF'
import json

with open('/workspace/contracts/openapi.contract.json') as f:
    c = json.load(f)

for path, methods in c['paths'].items():
    for method, details in methods.items():
        if method not in ('get','post','put','patch','delete'):
            continue
        op = details.get('operationId','?')
        req = details.get('requestBody', {})
        params = details.get('parameters', [])

        print(f"\n{'='*80}")
        print(f"{method.upper()} {path}  ->  {op}")
        print(f"{'='*80}")

        # Security
        sec = details.get('security', [])
        print(f"Security: {sec}")

        # Parameters
        if params:
            print(f"Path params: {json.dumps(params)}")

        # Request body
        if req:
            try:
                schema = req['content']['application/json']['schema']
                required = schema.get('required', [])
                props = schema.get('properties', {})
                print(f"Request (required={required}):")
                for pname, pdef in props.items():
                    ref = pdef.get('$ref', '')
                    fmt = pdef.get('format', '')
                    ptype = pdef.get('type', 'object' if ref else '?')
                    enum = pdef.get('enum', '')
                    extra = f" format={fmt}" if fmt else ''
                    extra += f" enum={enum}" if enum else ''
                    extra += f" $ref={ref}" if ref else ''
                    print(f"  {pname}: {ptype}{extra}")
            except:
                print(f"Request: [complex]")

        # Responses
        for code, resp in details.get('responses', {}).items():
            try:
                content = resp.get('content', {})
                if 'application/json' in content:
                    schema = content['application/json'].get('schema', {})
                    # Check for data envelope
                    props = schema.get('properties', {})
                    if 'data' in props:
                        dprops = props['data'].get('properties', {}) or props['data'].get('allOf', [{}])[0].get('properties', {})
                        if not dprops and '$ref' in props['data']:
                            print(f"  {code}: data -> $ref")
                        else:
                            dreq = props['data'].get('required', [])
                            print(f"  {code}: data{{required={dreq}}} fields={list(dprops.keys())[:15]}")
                    elif 'error' in props:
                        codes = props.get('code', {}).get('enum', [])
                        print(f"  {code}: error codes={codes}")
                    else:
                        print(f"  {code}: {list(props.keys())[:10]}")
                else:
                    print(f"  {code}: no content")
            except Exception as e:
                print(f"  {code}: parse error {e}")

PYEOF", "timeout": 30}

{"command": "create", "path": "/workspace/backend/store/db.go", "file_text": "package store

import (
	"context"
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"os"
	"sync/atomic"
	"time"

	_ "github.com/lib/pq"
	"go.mongodb.org/mongo-driver/bson"
	"go.mongodb.org/mongo-driver/mongo"
	"go.mongodb.org/mongo-driver/mongo/options"

	"github.com/go-redis/redis/v8"
	"github.com/google/uuid"
)

type Store struct {
	pg      *sql.DB
	mongo   *mongo.Database
	redis   *redis.Client
	eventSeq int64
}

func New(ctx context.Context) (*Store, error) {
	pgHost := os.Getenv("PGHOST")
	if pgHost == "" {
		pgHost = "/tmp"
	}
	mongoURI := os.Getenv("MONGO_URI")
	if mongoURI == "" {
		mongoURI = "mongodb://127.0.0.1:27017"
	}
	redisAddr := os.Getenv("REDIS_ADDR")
	if redisAddr == "" {
		redisAddr = "127.0.0.1:6379"
	}

	pgConnStr := fmt.Sprintf("host=%s user=agent dbname=lab_samples sslmode=disable", pgHost)
	pgDB, err := sql.Open("postgres", pgConnStr)
	if err != nil {
		return nil, fmt.Errorf("pg open: %w", err)
	}
	if err := pgDB.PingContext(ctx); err != nil {
		return nil, fmt.Errorf("pg ping: %w", err)
	}

	mongoClient, err := mongo.Connect(ctx, options.Client().ApplyURI(mongoURI))
	if err != nil {
		return nil, fmt.Errorf("mongo connect: %w", err)
	}
	mongoDB := mongoClient.Database("lab_samples")

	rdb := redis.NewClient(&redis.Options{Addr: redisAddr})
	if err := rdb.Ping(ctx).Err(); err != nil {
		return nil, fmt.Errorf("redis ping: %w", err)
	}

	s := &Store{pg: pgDB, mongo: mongoDB, redis: rdb}
	s.eventSeq = s.loadEventSeq(ctx)
	return s, nil
}

func (s *Store) PG() *sql.DB      { return s.pg }
func (s *Store) Mongo() *mongo.Database { return s.mongo }
func (s *Store) Redis() *redis.Client   { return s.redis }

func (s *Store) loadEventSeq(ctx context.Context) int64 {
	val, _ := s.redis.Get(ctx, "event:seq").Int64()
	return val
}

func (s *Store) NextEventID(ctx context.Context) int64 {
	return atomic.AddInt64(&s.eventSeq, 1)
}

func (s *Store) PersistEventSeq(ctx context.Context) {
	s.redis.Set(ctx, "event:seq", s.eventSeq, 0)
}

func (s *Store) EnsurePG(ctx context.Context) error {
	return s.pg.PingContext(ctx)
}

func (s *Store) EnsureMongo(ctx context.Context) error {
	return s.mongo.Client().Ping(ctx, nil)
}

func (s *Store) EnsureRedis(ctx context.Context) error {
	return s.redis.Ping(ctx).Err()
}

