func (h *Handler) UpdateAssignmentProgress(w http.ResponseWriter, r *http.Request) {
	var req struct {
		AssignmentID   string `json:"assignmentId"`
		Status         string `json:"status"`
		OccurredAt     string `json:"occurredAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		middleware.WriteError(w, 400, "invalid_json", "invalid json")
		return
	}

	uid := middleware.GetUserID(r)
	ctx := r.Context()
	occurredAt, _ := time.Parse(time.RFC3339, req.OccurredAt)
	if occurredAt.IsZero() {
		occurredAt = time.Now()
	}

	var assignStatus, kind, sampleID string
	err := h.store.PG().QueryRowContext(ctx, "SELECT status, kind, sample_id FROM assignments WHERE assignment_id=$1 AND worker_id=$2",
		req.AssignmentID, uid).Scan(&assignStatus, &kind, &sampleID)
	if err != nil {
		middleware.WriteError(w, 404, "not_found", "assignment not found")
		return
	}
	if assignStatus != "accepted" && assignStatus != "in_progress" {
		middleware.WriteError(w, 409, "assignment_inactive", "assignment not active")
		return
	}

	// Validate transitions
	validTransitions := map[string][]string{
		"at_pickup":  {"accepted", "in_progress"},
		"picked_up":  {"at_pickup"},
		"in_transit": {"picked_up", "at_pickup"},
		"arrived":    {"in_transit"},
		"delivered":  {"arrived"},
		"in_progress": {"accepted"},
		"completed":  {"accepted", "in_progress", "delivered"},
	}

	valid := false
	for _, allowed := range validTransitions[req.Status] {
		if assignStatus == allowed {
			valid = true
			break
		}
	}
	if !valid {
		middleware.WriteError(w, 409, "invalid_transition", "invalid status transition")
		return
	}

	h.store.PG().ExecContext(ctx, "UPDATE assignments SET progress_status=$1, updated_at=now() WHERE assignment_id=$2", req.Status, req.AssignmentID)
	if req.Status == "delivered" || req.Status == "completed" {
		h.store.PG().ExecContext(ctx, "UPDATE assignments SET status='completed', updated_at=now() WHERE assignment_id=$1", req.AssignmentID)
		if req.Status == "delivered" {
			h.store.PG().ExecContext(ctx, "UPDATE samples SET status='delivered', updated_at=now() WHERE sample_id=$1", sampleID)
		}
	}

	middleware.WriteJSON(w, 201, map[string]interface{}{
		"data": map[string]interface{}{
			"assignmentId": req.AssignmentID,
			"sampleId":     sampleID,
			"status":       req.Status,
		},
	})
}

