func (h *Handler) ListRoleWork(w http.ResponseWriter, r *http.Request) {
	uid := middleware.GetUserID(r)
	role := middleware.GetActiveRole(r)
	ctx := r.Context()

	result := models.RoleWork{
		Pending:    []interface{}{},
		InProgress: []interface{}{},
		Completed:  []interface{}{},
	}

	switch role {
	case "requester":
		rows, err := h.store.PG().QueryContext(ctx,
			`SELECT sample_id, request_id, status, serviceability, requested_at, delivery_deadline, earliest_collection_at, latest_collection_at, active_journey_id, target_laboratory_id, current_holder_id, location_recorded_at
			 FROM samples WHERE requester_id=$1 ORDER BY created_at DESC`, uid)
		if err == nil {
			defer rows.Close()
			for rows.Next() {
				var wi models.SampleWorkItem
				wi.Kind = "sample"
				wi.History = h.getTimeline(ctx, "")
				rows.Scan(&wi.SampleID, &wi.RequestID, &wi.Status, &wi.Serviceability, &wi.RequestedAt, &wi.DeliveryDeadline, &wi.EarliestCollectionAt, &wi.LatestCollectionAt, &wi.ActiveJourneyID, &wi.LaboratoryID, &wi.CurrentHolderID, &wi.LocationRecordedAt)
				wi.LocationStale = h.isLocationStale(wi.LocationRecordedAt)
				if wi.Status == "requested" || wi.Status == "assigned" || wi.Status == "offered" {
					result.Pending = append(result.Pending, wi)
				} else if wi.Status == "received" || wi.Status == "cancelled" || wi.Status == "expired" {
					result.Completed = append(result.Completed, wi)
				} else {
					result.InProgress = append(result.InProgress, wi)
				}
			}
		}

	case "collection_professional", "delivery_partner", "node_handler", "laboratory_team":
		rows, err := h.store.PG().QueryContext(ctx,
			`SELECT a.assignment_id, a.kind, a.sample_id, a.status, a.journey_id, a.from_location_id, a.to_location_id, a.sequence, a.offer_expires_at, a.node_id, a.laboratory_id, a.expected_sample_type_id
			 FROM assignments a WHERE a.worker_id=$1 ORDER BY a.created_at DESC`, uid)
		if err == nil {
			defer rows.Close()
			for rows.Next() {
				var wi models.AssignmentWorkItem
				wi.History = h.getTimeline(ctx, "")
				rows.Scan(&wi.AssignmentID, &wi.Kind, &wi.SampleID, &wi.Status, &wi.JourneyID, &wi.FromLocationID, &wi.ToLocationID, &wi.Sequence, &wi.OfferExpiresAt, &wi.NodeID, &wi.LaboratoryID, &wi.ExpectedSampleTypeID)
				switch wi.Status {
				case "offered":
					result.Pending = append(result.Pending, wi)
				case "accepted", "in_progress":
					result.InProgress = append(result.InProgress, wi)
				case "completed", "cancelled", "expired", "declined":
					result.Completed = append(result.Completed, wi)
				}
			}
		}
	}

	middleware.WriteJSON(w, 200, map[string]interface{}{"data": result})
}

