	if err := db.CreateDefaultSampleTypes(ctx); err != nil {
		log.Printf("default sample types: %v", err)
	}

	h := handlers.New(db)

	mux := http.NewServeMux()

	// System
	mux.HandleFunc("/ready", h.SystemReadiness)

	// Auth (no auth required)
	mux.HandleFunc("/api/authenticate-user", h.AuthenticateUser)

	// Authenticated routes
	auth := middleware.AuthMiddleware

	// Bootstrap
	mux.Handle("GET /api/ui/bootstrap", auth(http.HandlerFunc(h.ReadUIBootstrap)))

	// User management
	mux.Handle("POST /api/create-user", auth(http.HandlerFunc(h.CreateUser)))
	mux.Handle("GET /api/read-user/{userId}", auth(http.HandlerFunc(h.ReadUser)))
	mux.Handle("POST /api/update-user-access", auth(http.HandlerFunc(h.UpdateUserAccess)))
	mux.Handle("POST /api/select-active-role", auth(http.HandlerFunc(h.SelectActiveRole)))

	// Locations
	mux.Handle("POST /api/create-location", auth(http.HandlerFunc(h.CreateLocation)))
	mux.Handle("POST /api/update-location", auth(http.HandlerFunc(h.UpdateLocation)))
	mux.Handle("POST /api/set-location-status", auth(http.HandlerFunc(h.SetLocationStatus)))
	mux.Handle("POST /api/set-location-function-status", auth(http.HandlerFunc(h.SetLocationFunctionStatus)))

	// Connections
	mux.Handle("POST /api/create-connection", auth(http.HandlerFunc(h.CreateConnection)))
	mux.Handle("POST /api/set-connection-status", auth(http.HandlerFunc(h.SetConnectionStatus)))

	// Sample types
	mux.Handle("POST /api/create-sample-type", auth(http.HandlerFunc(h.CreateSampleType)))
	mux.Handle("POST /api/update-sample-type", auth(http.HandlerFunc(h.UpdateSampleType)))

	// Capacity & Laboratory acceptance
	mux.Handle("POST /api/configure-capacity", auth(http.HandlerFunc(h.ConfigureCapacity)))
	mux.Handle("POST /api/configure-laboratory-acceptance", auth(http.HandlerFunc(h.ConfigureLaboratoryAcceptance)))

	// Serviceability
	mux.Handle("POST /api/check-serviceability", auth(http.HandlerFunc(h.CheckServiceability)))
	mux.Handle("POST /api/read-serviceability-snapshot", auth(http.HandlerFunc(h.ReadServiceabilitySnapshot)))

	// Collection requests
	mux.Handle("POST /api/create-collection-request", auth(http.HandlerFunc(h.CreateCollectionRequest)))

	// Sample lifecycle
	mux.Handle("POST /api/collect-and-seal-sample", auth(http.HandlerFunc(h.CollectAndSealSample)))
	mux.Handle("POST /api/ingest-presealed-sample", auth(http.HandlerFunc(h.IngestPresealedSample)))
	mux.Handle("GET /api/read-sample-state/{sampleId}", auth(http.HandlerFunc(h.ReadSampleState)))
	mux.Handle("POST /api/read-sample-lifecycle", auth(http.HandlerFunc(h.ReadSampleLifecycle)))

	// Assignments
	mux.Handle("POST /api/accept-assignment", auth(http.HandlerFunc(h.AcceptAssignment)))
	mux.Handle("POST /api/decline-assignment", auth(http.HandlerFunc(h.DeclineAssignment)))
	mux.Handle("POST /api/update-assignment-progress", auth(http.HandlerFunc(h.UpdateAssignmentProgress)))

	// Worker location and availability
	mux.Handle("POST /api/record-worker-location", auth(http.HandlerFunc(h.RecordWorkerLocation)))
	mux.Handle("POST /api/set-worker-availability", auth(http.HandlerFunc(h.SetWorkerAvailability)))

	// Handoffs
	mux.Handle("POST /api/initiate-handoff", auth(http.HandlerFunc(h.InitiateHandoff)))
	mux.Handle("POST /api/confirm-handoff", auth(http.HandlerFunc(h.ConfirmHandoff)))

	// Laboratory
	mux.Handle("POST /api/confirm-laboratory-receipt", auth(http.HandlerFunc(h.ConfirmLaboratoryReceipt)))
	mux.Handle("POST /api/record-laboratory-exception", auth(http.HandlerFunc(h.RecordLaboratoryException)))

	// Handling checkpoint
	mux.Handle("POST /api/record-handling-checkpoint", auth(http.HandlerFunc(h.RecordHandlingCheckpoint)))

	// Journey management
	mux.Handle("POST /api/read-journey-plan", auth(http.HandlerFunc(h.ReadJourneyPlan)))
	mux.Handle("POST /api/cancel-journey", auth(http.HandlerFunc(h.CancelJourney)))
	mux.Handle("POST /api/edit-active-plan", auth(http.HandlerFunc(h.EditActivePlan)))
	mux.Handle("POST /api/split-journey", auth(http.HandlerFunc(h.SplitJourney)))
	mux.Handle("POST /api/merge-journeys", auth(http.HandlerFunc(h.MergeJourneys)))
	mux.Handle("POST /api/reroute-journey", auth(http.HandlerFunc(h.RerouteJourney)))
	mux.Handle("POST /api/report-disruption", auth(http.HandlerFunc(h.ReportDisruption)))

	// Role work
	mux.Handle("POST /api/list-role-work", auth(http.HandlerFunc(h.ListRoleWork)))

	// Operations state
	mux.Handle("POST /api/read-operations-state", auth(http.HandlerFunc(h.ReadOperationsState)))

	// Audit
	mux.Handle("POST /api/search-audit-trail", auth(http.HandlerFunc(h.SearchAuditTrail)))

	// WebSocket
	mux.HandleFunc("GET /api/events", h.StreamRealtimeEvents)

	// Simple CORS
	handler := corsMiddleware(mux)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Listening on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, handler))
}

func corsMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Access-Control-Allow-Origin", "*")
		w.Header().Set("Access-Control-Allow-Methods", "GET, POST, OPTIONS")
		w.Header().Set("Access-Control-Allow-Headers", "Authorization, Content-Type")

		if r.Method == "OPTIONS" {
			w.WriteHeader(200)
			return
		}

		// Handle non-standard POST-based reads with method override
		if r.Method == "GET" && strings.HasPrefix(r.URL.Path, "/api/") {
			next.ServeHTTP(w, r)
			return
		}

		next.ServeHTTP(w, r)
	})
}

// Logging
func init() {
	log.SetFlags(log.LstdFlags | log.Lmicroseconds)
}"}

