{"command": "create", "path": "/workspace/frontend/src/api/client.ts", "file_text": "import type {
  AuthUser,
  BootstrapData,
  Location,
  Connection,
  SampleType,
  SampleState,
  SampleLifecycle,
  JourneyPlan,
  WorkerJourneyPlan,
  RequesterJourneyPlan,
  RoleWork,
  OperationsState,
  AuditSearchResult,
  ServiceabilityResult,
  ServiceabilityRegion,
  Capacity,
  AssignmentWorkItem,
} from '../types';

const BASE = '/api';

let sessionToken: string | null = localStorage.getItem('token');
let activeRole: string | null = localStorage.getItem('activeRole');

export function setSession(token: string | null) {
  sessionToken = token;
  if (token) localStorage.setItem('token', token);
  else localStorage.removeItem('token');
}

export function setActiveRole(role: string | null) {
  activeRole = role;
  if (role) localStorage.setItem('activeRole', role);
  else localStorage.removeItem('activeRole');
}

export function getActiveRole(): string | null {
  return activeRole;
}

async function request<T>(method: string, path: string, body?: unknown): Promise<T> {
  const headers: Record<string, string> = { 'Content-Type': 'application/json' };
  if (sessionToken) headers['Authorization'] = `Bearer ${sessionToken}`;
  if (activeRole) headers['X-Active-Role'] = activeRole;

  const res = await fetch(`${BASE}${path}`, {
    method,
    headers,
    body: body ? JSON.stringify(body) : undefined,
  });

  if (res.status === 401) {
    setSession(null);
    window.location.href = '/login';
    throw new Error('Unauthorized');
  }

  const data = await res.json();
  if (!res.ok) {
    throw new Error(data.error || data.code || 'Request failed');
  }
  return data;
}

// Auth
export function authenticateUser(username: string, password: string) {
  return request<{ data: { user: AuthUser; token: string } }>('POST', '/authenticate-user', { username, password });
}

export function selectActiveRole(role: string) {
  return request<{ data: { activeRole: string } }>('POST', '/select-active-role', { role });
}

// Bootstrap
export function readUIBootstrap() {
  return request<{ data: BootstrapData }>('GET', '/ui/bootstrap');
}

