  username: string;
  initialPassword: string;
  email?: string;
  fullName?: string;
  phone?: string;
  roles: string[];
  qualifications?: string[];
  certifications?: { code: string; active: boolean; expiresAt?: string }[];
  active: boolean;
  assignedLocationId?: string;
}) {
  return request<{ data: { userId: string } }>('POST', '/create-user', params);
}

export function readUser(userId: string) {
  return request<{ data: AuthUser }>('GET', `/read-user/${userId}`);
}

export function updateUserAccess(params: {
  userId: string;
  roles: string[];
  qualifications?: string[];
  certifications?: { code: string; active: boolean; expiresAt?: string }[];
  active: boolean;
  assignedLocationId?: string;
}) {
  return request<{ data: { userId: string } }>('POST', '/update-user-access', params);
}

// Locations
export function createLocation(params: {
  name: string;
  coordinate: { latitude: number; longitude: number };
  coverageKm?: number;
  handlingMinutes?: number;
  active: boolean;
  functions: Record<string, boolean>;
}) {
  return request<{ data: { locationId: string } }>('POST', '/create-location', params);
}

export function updateLocation(params: {
  locationId: string;
  name: string;
  coordinate: { latitude: number; longitude: number };
  coverageKm?: number;
  handlingMinutes?: number;
  functions?: Record<string, boolean>;
}) {
  return request<{ data: { locationId: string } }>('POST', '/update-location', params);
}

export function setLocationStatus(locationId: string, active: boolean) {
  return request<{ data: { locationId: string } }>('POST', '/set-location-status', { locationId, active });
}

export function setLocationFunctionStatus(locationId: string, func: string, active: boolean) {
  return request<{ data: { locationId: string } }>('POST', '/set-location-function-status', { locationId, function: func, active });
}

// Connections
export function createConnection(params: {
  fromLocationId: string;
  toLocationId: string;
  travelMinutes: number;
  costUnits?: number;
  cooled?: boolean;
  active: boolean;
}) {
  return request<{ data: { connectionId: string } }>('POST', '/create-connection', params);
}

export function setConnectionStatus(connectionId: string, active: boolean) {
  return request<{ data: { connectionId: string } }>('POST', '/set-connection-status', { connectionId, active });
}

// Sample types
export function createSampleType(params: {
  name: string;
  qualifiedCollectorRequired?: boolean;
  requiredQualification?: string;
  containerType: string;
  temperatureMinC: number;
  temperatureMaxC: number;
  incompatibleSampleTypes?: string[];
  requiresCooledRoute?: boolean;
  batchingAllowed?: boolean;
}) {
  return request<{ data: { sampleTypeId: string } }>('POST', '/create-sample-type', params);
}

export function updateSampleType(params: {
  sampleTypeId: string;
  qualifiedCollectorRequired?: boolean;
