  const [deadline, setDeadline] = useState('');
  const [earliestCol, setEarliestCol] = useState('');
  const [latestCol, setLatestCol] = useState('');
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  const sampleTypes: SampleType[] = bootstrap?.sampleTypes || [];

  async function handleCheck() {
    setError('');
    try {
      const res = await checkServiceability({
        origin: { latitude: parseFloat(originLat), longitude: parseFloat(originLng) },
        originType,
        originNodeId: originNodeId || undefined,
        sampleTypeId,
        requestedAt: new Date().toISOString(),
        deliveryDeadline: new Date(deadline).toISOString(),
        earliestCollectionAt: earliestCol ? new Date(earliestCol).toISOString() : undefined,
        latestCollectionAt: latestCol ? new Date(latestCol).toISOString() : undefined,
      });
      setSuccess(`Serviceable: ${res.data.serviceable}${res.data.reason ? ' - ' + res.data.reason : ''}`);
    } catch (e: unknown) {
      setError(e instanceof Error ? e.message : 'Check failed');
    }
  }

  async function handleSubmit(e: FormEvent) {
    e.preventDefault();
    setError('');
    setSuccess('');
    try {
      const res = await createCollectionRequest({
        origin: { latitude: parseFloat(originLat), longitude: parseFloat(originLng) },
        originType,
        originNodeId: originNodeId || undefined,
        requestedAt: new Date().toISOString(),
        deliveryDeadline: new Date(deadline).toISOString(),
        earliestCollectionAt: earliestCol ? new Date(earliestCol).toISOString() : undefined,
        latestCollectionAt: latestCol ? new Date(latestCol).toISOString() : undefined,
        sampleTypeId,
        containerType,
        temperatureMinC: parseFloat(tempMin),
        temperatureMaxC: parseFloat(tempMax),
        idempotencyKey: crypto.randomUUID(),
      });
      setSuccess(`Request created! Sample: ${(res.data as {sampleId: string}).sampleId}`);
      setTimeout(() => navigate(`/samples/${(res.data as {sampleId: string}).sampleId}`), 1000);
    } catch (e: unknown) {
      setError(e instanceof Error ? e.message : 'Creation failed');
    }
  }

  return (
    <div>
