              <input type="number" step="any" value={originLat} onChange={e => setOriginLat(e.target.value)} required />
            </div>
            <div className="form-group">
              <label>Origin Longitude</label>
              <input type="number" step="any" value={originLng} onChange={e => setOriginLng(e.target.value)} required />
            </div>
          </div>

          <div className="grid grid-2">
            <div className="form-group">
              <label>Origin Type</label>
              <select value={originType} onChange={e => setOriginType(e.target.value)}>
                <option value="home">Home</option>
                <option value="clinic">Clinic</option>
                <option value="node">Node</option>
              </select>
            </div>
            <div className="form-group">
              <label>Sample Type</label>
              <select value={sampleTypeId} onChange={e => setSampleTypeId(e.target.value)} required>
                <option value="">— Select —</option>
                {sampleTypes.map(st => (
                  <option key={st.sampleTypeId} value={st.sampleTypeId}>{st.name}</option>
                ))}
              </select>
            </div>
          </div>

          <div className="grid grid-2">
            <div className="form-group">
              <label>Container Type</label>
              <input value={containerType} onChange={e => setContainerType(e.target.value)} required />
            </div>
            <div className="form-group">
              <label>Delivery Deadline</label>
              <input type="datetime-local" value={deadline} onChange={e => setDeadline(e.target.value)} required />
            </div>
          </div>

          <div className="grid grid-3">
            <div className="form-group">
              <label>Temp Min (°C)</label>
              <input type="number" step="any" value={tempMin} onChange={e => setTempMin(e.target.value)} />
            </div>
            <div className="form-group">
              <label>Temp Max (°C)</label>
              <input type="number" step="any" value={tempMax} onChange={e => setTempMax(e.target.value)} />
            </div>
          </div>

          <div className="grid grid-2">
            <div className="form-group">
              <label>Earliest Collection</label>
              <input type="datetime-local" value={earliestCol} onChange={e => setEarliestCol(e.target.value)} />
            </div>
            <div className="form-group">
              <label>Latest Collection</label>
              <input type="datetime-local" value={latestCol} onChange={e => setLatestCol(e.target.value)} />
            </div>
          </div>

          {error && <div className="error-text">{error}</div>}
          {success && <div style={{ color: 'var(--success)' }}>{success}</div>}

          <div className="flex gap-1">
            <button className="btn btn-primary" type="submit">Create Request</button>
            <button className="btn" type="button" onClick={handleCheck}>Check Serviceability</button>
          </div>
        </form>
      </div>
    </div>
  );
}"}

{"command": "create", "path": "/workspace/frontend/src/pages/ServiceabilityCheck.tsx", "file_text": "import { useState } from 'react';
import { checkServiceability, readServiceabilitySnapshot } from '../api/client';
import type { ServiceabilityResult, ServiceabilityRegion, SampleType } from '../types';
import { useAuth } from '../context/AuthContext';

export default function ServiceabilityCheck() {
  const { bootstrap } = useAuth();
  const [originLat, setOriginLat] = useState('');
  const [originLng, setOriginLng] = useState('');
  const [sampleTypeId, setSampleTypeId] = useState('');
  const [deadline, setDeadline] = useState('');
  const [result, setResult] = useState<ServiceabilityResult | null>(null);
  const [regions, setRegions] = useState<ServiceabilityRegion[] | null>(null);
  const [error, setError] = useState('');

  const sampleTypes: SampleType[] = bootstrap?.sampleTypes || [];

  async function handleCheck() {
    setError('');
    setResult(null);
    try {
      const res = await checkServiceability({
        origin: { latitude: parseFloat(originLat), longitude: parseFloat(originLng) },
        sampleTypeId,
        requestedAt: new Date().toISOString(),
        deliveryDeadline: new Date(deadline).toISOString(),
      });
      setResult(res.data);
    } catch (e: unknown) {
      setError(e instanceof Error ? e.message : 'Check failed');
    }
  }

  async function loadRegions() {
    try {
      const res = await readServiceabilitySnapshot();
      setRegions(res.data);
    } catch (e: unknown) {
      setError(e instanceof Error ? e.message : 'Failed to load regions');
    }
  }

  return (
    <div>
      <div className="page-header">
        <h1 className="page-title">Serviceability Check</h1>
      </div>
      <p className="text-sm text-secondary mb-2">This is a dry run — no request, sample, or assignment is created.</p>

      <div className="grid grid-2">
        <div className="card" style={{ padding: '1.5rem' }}>
          <div className="flex-col gap-2">
            <div className="form-group">
              <label>Origin Latitude</label>
              <input type="number" step="any" value={originLat} onChange={e => setOriginLat(e.target.value)} />
            </div>
            <div className="form-group">
              <label>Origin Longitude</label>
              <input type="number" step="any" value={originLng} onChange={e => setOriginLng(e.target.value)} />
            </div>
            <div className="form-group">
              <label>Sample Type</label>
              <select value={sampleTypeId} onChange={e => setSampleTypeId(e.target.value)}>
                <option value="">— Select —</option>
                {sampleTypes.map(st => (
                  <option key={st.sampleTypeId} value={st.sampleTypeId}>{st.name}</option>
                ))}
              </select>
            </div>
            <div className="form-group">
              <label>Delivery Deadline</label>
              <input type="datetime-local" value={deadline} onChange={e => setDeadline(e.target.value)} />
            </div>
            <button className="btn btn-primary" onClick={handleCheck}>Check</button>
            <button className="btn" onClick={loadRegions}>Load All Service Regions</button>
          </div>
          {error && <div className="error-text mt-1">{error}</div>}
          {result && (
            <div className="card mt-2" style={{ padding: '1rem', background: result.serviceable ? '#f0fdf4' : '#fef2f2' }}>
              <div className="font-bold">{result.serviceable ? '✓ Serviceable' : '✗ Not Serviceable'}</div>
              {result.reason && <div className="text-sm">{result.reason}</div>}
              {result.estimatedDeliveryAt && <div className="text-sm">Est Delivery: {new Date(result.estimatedDeliveryAt).toLocaleString()}</div>}
              {result.matchedLaboratoryId && <div className="text-sm">Lab: {result.matchedLaboratoryId}</div>}
            </div>
          )}
        </div>

        {regions && (
          <div className="card" style={{ padding: '1rem' }}>
            <h3 className="mb-2">Service Regions ({regions.length})</h3>
            <div style={{ maxHeight: '400px', overflow: 'auto' }}>
              <table className="table">
                <thead>
                  <tr><th>Location</th><th>Name</th><th>Coverage (km)</th></tr>
                </thead>
                <tbody>
                  {regions.map((r) => (
                    <tr key={r.locationId}>
                      <td>{r.locationId.slice(0, 8)}...</td>
                      <td>{r.name}</td>
                      <td>{r.coverageKm}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}"}

{"command": "create", "path": "/workspace/frontend/src/pages/WorkView.tsx", "file_text": "import { useEffect, useState } from 'react';
import { useAuth } from '../context/AuthContext';
import { listRoleWork, acceptAssignment, declineAssignment, updateAssignmentProgress } from '../api/client';
import type { SampleWorkItem, AssignmentWorkItem, JourneyWorkItem } from '../types';
import { useNavigate } from 'react-router-dom';

type WorkItem = SampleWorkItem | AssignmentWorkItem | JourneyWorkItem;

export default function WorkView() {
  const { user } = useAuth();
  const navigate = useNavigate();
  const [work, setWork] = useState<{ pending: WorkItem[]; inProgress: WorkItem[]; completed: WorkItem[] }>({ pending: [], inProgress: [], completed: [] });
  const [tab, setTab] = useState<'pending' | 'inProgress' | 'completed'>('pending');
  const [msg, setMsg] = useState('');

  useEffect(() => { load(); }, [user?.activeRole]);

  async function load() {
    if (!user?.activeRole) return;
    try {
      const res = await listRoleWork(user.activeRole);
      setWork({
        pending: res.data.pending as WorkItem[],
        inProgress: res.data.inProgress as WorkItem[],
        completed: res.data.completed as WorkItem[],
      });
    } catch { /* ignore */ }
  }

  async function handleAccept(asstId: string) {
    try {
      await acceptAssignment(asstId);
      setMsg('Accepted');
      load();
    } catch (e: unknown) { setMsg(e instanceof Error ? e.message : 'Error'); }
  }

  async function handleDecline(asstId: string) {
    try {
      await declineAssignment(asstId);
      setMsg('Declined');
      load();
    } catch (e: unknown) { setMsg(e instanceof Error ? e.message : 'Error'); }
  }

  async function handleProgress(asstId: string, status: string) {
    try {
      await updateAssignmentProgress(asstId, status);
      setMsg(`Updated to ${status}`);
      load();
    } catch (e: unknown) { setMsg(e instanceof Error ? e.message : 'Error'); }
  }

  const items = work[tab];

  return (
    <div>
      <div className="page-header">
        <h1 className="page-title">My Work</h1>
      </div>

      {msg && <div className="card mb-2" style={{ padding: '0.5rem 1rem', background: '#f0fdf4' }}>{msg}</div>}

      <div className="flex gap-1 mb-2">
        {(['pending', 'inProgress', 'completed'] as const).map((t) => (
          <button key={t} className={`btn btn-sm ${tab === t ? 'btn-primary' : ''}`} onClick={() => setTab(t)}>
            {t === 'inProgress' ? 'In Progress' : t.charAt(0).toUpperCase() + t.slice(1)} ({work[t].length})
          </button>
        ))}
      </div>

      <div className="flex-col gap-1">
        {items.length === 0 && <p className="text-sm text-secondary">No {tab} work</p>}
        {items.map((w) => {
          const id = (w as SampleWorkItem).sampleId || (w as AssignmentWorkItem).assignmentId || (w as JourneyWorkItem).journeyId;
          const isAsst = w.kind !== 'sample' && w.kind !== 'journey';
          const asst = w as AssignmentWorkItem;
          return (
            <div key={w.kind + id} className="card" style={{ padding: '0.75rem' }}>
              <div className="flex-between">
                <div>
                  <span className="badge badge-active">{w.kind}</span>
                  {' '}
                  <span className="font-bold">{id?.slice(0, 12)}...</span>
                  {' '}
                  <span className={`badge ${w.status === 'offered' ? 'badge-pending' : w.status === 'completed' ? 'badge-complete' : 'badge-active'}`}>
                    {w.status}
                  </span>
                </div>
                <div className="flex gap-1">
                  {isAsst && w.status === 'offered' && (
                    <>
                      <button className="btn btn-sm btn-primary" onClick={() => handleAccept(asst.assignmentId)}>Accept</button>
                      <button className="btn btn-sm btn-danger" onClick={() => handleDecline(asst.assignmentId)}>Decline</button>
                    </>
                  )}
                  {isAsst && w.status === 'accepted' && (
                    <button className="btn btn-sm btn-primary" onClick={() => handleProgress(asst.assignmentId, 'in_progress')}>Start</button>
                  )}
                  {isAsst && w.status === 'in_progress' && (
                    <button className="btn btn-sm btn-primary" onClick={() => handleProgress(asst.assignmentId, 'completed')}>Complete</button>
                  )}
                  <button className="btn btn-sm" onClick={() => w.kind === 'sample' && navigate(`/samples/${(w as SampleWorkItem).sampleId}`)}>
                    View
                  </button>
                </div>
              </div>
              <div className="text-sm text-secondary mt-1">
                {w.kind === 'sample' && `Request: ${(w as SampleWorkItem).requestId?.slice(0, 8)}... | Deadline: ${(w as SampleWorkItem).deliveryDeadline ? new Date((w as SampleWorkItem).deliveryDeadline!).toLocaleString() : '—'}`}
                {isAsst && asst.fromLocationId && `From: ${asst.fromLocationId.slice(0, 8)}... → ${asst.toLocationId?.slice(0, 8) || '—'}`}
              </div>
              {w.history && w.history.length > 0 && (
                <ul className="timeline mt-1">
                  {w.history.slice(-3).map((h, i) => (
                    <li key={i}>
                      <span>{h.action}</span>
                      <span className="text-sm text-secondary">{new Date(h.occurredAt).toLocaleString()}</span>
                    </li>
                  ))}
                </ul>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}"}

{"command": "create", "path": "/workspace/frontend/src/pages/OperationsMonitor.tsx", "file_text": "import { useEffect, useState, useCallback } from 'react';
import { readOperationsState, reportDisruption, rerouteJourney, cancelJourney } from '../api/client';
import type { OperationsState } from '../types';
import { useAuth } from '../context/AuthContext';

export default function OperationsMonitor() {
  const { hasRole } = useAuth();
  const [state, setState] = useState<OperationsState | null>(null);
  const [msg, setMsg] = useState('');
  const [disruptionType, setDisruptionType] = useState('worker');
  const [disruptionId, setDisruptionId] = useState('');

  const load = useCallback(async () => {
    try {
      const res = await readOperationsState();
      setState(res.data);
    } catch { /* ignore */ }
  }, []);

  useEffect(() => { load(); }, [load]);

  async function handleDisruption() {
    try {
      await reportDisruption(disruptionType, disruptionId);
      setMsg('Disruption reported');
      load();
    } catch (e: unknown) { setMsg(e instanceof Error ? e.message : 'Error'); }
  }

  if (!state) return <p className="text-secondary">Loading operations state...</p>;

  return (
    <div>
      <div className="page-header">
        <h1 className="page-title">Operations Monitor</h1>
        <button className="btn" onClick={load}>Refresh</button>
      </div>

      {msg && <div className="card mb-2" style={{ padding: '0.5rem 1rem', background: '#f0fdf4' }}>{msg}</div>}

      <div className="grid grid-3 mb-2">
        <div className="card" style={{ padding: '1rem' }}>
          <div className="font-bold">Samples</div>
          <div className="text-2xl">{state.samples?.length || 0}</div>
        </div>
        <div className="card" style={{ padding: '1rem' }}>
          <div className="font-bold">Workers</div>
          <div className="text-2xl">{state.workers?.length || 0}</div>
        </div>
        <div className="card" style={{ padding: '1rem' }}>
          <div className="font-bold">Locations</div>
          <div className="text-2xl">{state.locations?.length || 0}</div>
        </div>
        <div className="card" style={{ padding: '1rem' }}>
          <div className="font-bold">Connections</div>
          <div className="text-2xl">{state.connections?.length || 0}</div>
        </div>
        <div className="card" style={{ padding: '1rem' }}>
          <div className="font-bold">Handoffs</div>
          <div className="text-2xl">{state.handoffs?.length || 0}</div>
        </div>
        <div className="card" style={{ padding: '1rem' }}>
          <div className="font-bold">Exceptions</div>
          <div className="text-2xl" style={{ color: state.exceptions?.length ? 'var(--danger)' : 'var(--success)' }}>{state.exceptions?.length || 0}</div>
        </div>
      </div>

      <div className="grid grid-2">
        <div className="card" style={{ padding: '1rem' }}>
          <h3 className="mb-2">Locations ({state.locations?.length})</h3>
          <div style={{ maxHeight: '300px', overflow: 'auto' }}>
            <table className="table">
              <thead>
                <tr><th>ID</th><th>Name</th><th>Active</th><th>Functions</th><th>Capacity</th></tr>
              </thead>
              <tbody>
                {state.locations?.map((loc) => (
                  <tr key={loc.locationId || loc.id}>
                    <td>{(loc.locationId || loc.id)?.slice(0, 8)}...</td>
                    <td>{loc.name}</td>
                    <td><span className={`badge ${loc.active ? 'badge-complete' : 'badge-exception'}`}>{loc.active ? 'Yes' : 'No'}</span></td>
                    <td className="text-sm">{Object.entries(loc.functions).filter(([_, v]) => v).map(([k]) => k).join(', ')}</td>
                    <td className="text-sm">{loc.capacity ? `${loc.capacity.capacityUnits}u` : '—'}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>

        <div className="card" style={{ padding: '1rem' }}>
          <h3 className="mb-2">Connections ({state.connections?.length})</h3>
          <div style={{ maxHeight: '300px', overflow: 'auto' }}>
            <table className="table">
              <thead>
                <tr><th>ID</th><th>From</th><th>To</th><th>Time</th><th>Cooled</th><th>Active</th></tr>
              </thead>
              <tbody>
                {state.connections?.map((conn) => (
                  <tr key={conn.connectionId || conn.id}>
                    <td>{(conn.connectionId || conn.id)?.slice(0, 8)}...</td>
                    <td>{conn.fromLocationId?.slice(0, 8)}...</td>
                    <td>{conn.toLocationId?.slice(0, 8)}...</td>
                    <td>{conn.travelMinutes}m</td>
                    <td>{conn.cooled ? '✓' : '—'}</td>
                    <td><span className={`badge ${conn.active ? 'badge-complete' : 'badge-exception'}`}>{conn.active ? 'Yes' : 'No'}</span></td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </div>

      {hasRole('dispatcher', 'administrator') && (
        <div className="card mt-2" style={{ padding: '1rem' }}>
          <h3 className="mb-2">Report Disruption</h3>
          <div className="flex gap-1">
            <select className="form-group" value={disruptionType} onChange={e => setDisruptionType(e.target.value)}>
              <option value="worker">Worker</option>
              <option value="node">Node</option>
              <option value="connection">Connection</option>
              <option value="laboratory">Laboratory</option>
            </select>
            <input className="form-group" placeholder="Resource ID" value={disruptionId} onChange={e => setDisruptionId(e.target.value)} />
            <button className="btn btn-danger" onClick={handleDisruption}>Report</button>
          </div>
        </div>
      )}
    </div>
  );
}"}

{"command": "create", "path": "/workspace/frontend/src/pages/SampleTypeView.tsx", "file_text": "import { useEffect, useState } from 'react';
import { useAuth } from '../context/AuthContext';
import { createSampleType, updateSampleType, readUIBootstrap } from '../api/client';
import type { SampleType } from '../types';

export default function SampleTypeView() {
  const { bootstrap, refreshBootstrap } = useAuth();
  const [types, setTypes] = useState<SampleType[]>([]);
  const [showNew, setShowNew] = useState(false);
  const [editId, setEditId] = useState<string | null>(null);
  const [name, setName] = useState('');
  const [container, setContainer] = useState('standard');
  const [tempMin, setTempMin] = useState('0');
  const [tempMax, setTempMax] = useState('30');
  const [cooled, setCooled] = useState(false);
  const [batch, setBatch] = useState(true);
  const [collectorReq, setCollectorReq] = useState(false);
  const [qualification, setQualification] = useState('');
  const [msg, setMsg] = useState('');

  useEffect(() => {
    if (bootstrap?.sampleTypes) setTypes(bootstrap.sampleTypes);
  }, [bootstrap]);

  async function handleCreate() {
    try {
      await createSampleType({ name, containerType: container, temperatureMinC: parseFloat(tempMin), temperatureMaxC: parseFloat(tempMax), requiresCooledRoute: cooled, batchingAllowed: batch, qualifiedCollectorRequired: collectorReq, requiredQualification: qualification });
      setMsg('Created');
      await refreshBootstrap();
      setShowNew(false);
    } catch (e: unknown) { setMsg(e instanceof Error ? e.message : 'Error'); }
  }

  async function handleUpdate() {
    try {
      await updateSampleType({ sampleTypeId: editId!, containerType: container, temperatureMinC: parseFloat(tempMin), temperatureMaxC: parseFloat(tempMax), requiresCooledRoute: cooled, batchingAllowed: batch, qualifiedCollectorRequired: collectorReq, requiredQualification: qualification });
      setMsg('Updated');
      await refreshBootstrap();
      setEditId(null);
    } catch (e: unknown) { setMsg(e instanceof Error ? e.message : 'Error'); }
  }

  function startEdit(t: SampleType) {
    setEditId(t.sampleTypeId);
    setName(t.name);
    setContainer(t.containerType);
    setTempMin(String(t.temperatureMinC));
    setTempMax(String(t.temperatureMaxC));
    setCooled(t.requiresCooledRoute);
    setBatch(t.batchingAllowed);
    setCollectorReq(t.qualifiedCollectorRequired);
    setQualification(t.requiredQualification);
  }

  return (
    <div>
      <div className="page-header">
        <h1 className="page-title">Sample Types</h1>
        <button className="btn btn-primary" onClick={() => setShowNew(true)}>New Type</button>
      </div>

      {msg && <div className="card mb-2" style={{ padding: '0.5rem 1rem' }}>{msg}</div>}

      {(showNew || editId) && (
        <div className="card mb-2" style={{ padding: '1rem' }}>
          <h3 className="mb-2">{showNew ? 'New Sample Type' : 'Edit Sample Type'}</h3>
          <div className="grid grid-3">
            <div className="form-group">
              <label>Name</label>
              <input value={name} onChange={e => setName(e.target.value)} disabled={!!editId} />
            </div>
            <div className="form-group">
              <label>Container Type</label>
              <input value={container} onChange={e => setContainer(e.target.value)} />
            </div>
            <div className="form-group">
              <label>Qualification</label>
              <input value={qualification} onChange={e => setQualification(e.target.value)} placeholder="If collector required" />
            </div>
            <div className="form-group">
              <label>Temp Min (°C)</label>
              <input type="number" step="any" value={tempMin} onChange={e => setTempMin(e.target.value)} />
            </div>
            <div className="form-group">
              <label>Temp Max (°C)</label>
              <input type="number" step="any" value={tempMax} onChange={e => setTempMax(e.target.value)} />
            </div>
          </div>
          <div className="flex gap-2 mt-2">
            <label className="text-sm"><input type="checkbox" checked={cooled} onChange={e => setCooled(e.target.checked)} /> Requires Cooled</label>
            <label className="text-sm"><input type="checkbox" checked={batch} onChange={e => setBatch(e.target.checked)} /> Batching Allowed</label>
            <label className="text-sm"><input type="checkbox" checked={collectorReq} onChange={e => setCollectorReq(e.target.checked)} /> Qualified Collector Required</label>
          </div>
          <div className="flex gap-1 mt-2">
            {showNew && <button className="btn btn-primary" onClick={handleCreate}>Create</button>}
            {editId && <button className="btn btn-primary" onClick={handleUpdate}>Update</button>}
            <button className="btn" onClick={() => { setShowNew(false); setEditId(null); }}>Cancel</button>
          </div>
        </div>
      )}

      <div className="card" style={{ padding: '1rem' }}>
        <table className="table">
          <thead>
            <tr><th>Name</th><th>Container</th><th>Temp Range</th><th>Cooled</th><th>Batch</th><th>Collector Req.</th><th></th></tr>
          </thead>
          <tbody>
            {types.map((t) => (
              <tr key={t.sampleTypeId}>
                <td className="font-bold">{t.name}</td>
                <td>{t.containerType}</td>
                <td>{t.temperatureMinC}–{t.temperatureMaxC}°C</td>
                <td>{t.requiresCooledRoute ? '✓' : '—'}</td>
                <td>{t.batchingAllowed ? '✓' : '—'}</td>
                <td>{t.qualifiedCollectorRequired ? `${t.requiredQualification}` : '—'}</td>
                <td><button className="btn btn-sm" onClick={() => startEdit(t)}>Edit</button></td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}"}

{"command": "create", "path": "/workspace/frontend/src/pages/LocationView.tsx", "file_text": "import { useEffect, useState } from 'react';
import { createLocation, updateLocation, setLocationStatus, setLocationFunctionStatus, createConnection, setConnectionStatus, configureCapacity } from '../api/client';
import { readUIBootstrap } from '../api/client';
import { useAuth } from '../context/AuthContext';
import type { Location, Connection, ConnectionType } from '../types';

export default function LocationView() {
  const { bootstrap, refreshBootstrap, hasRole } = useAuth();
  const [locations, setLocations] = useState<Location[]>([]);
  const [connections, setConnections] = useState<ConnectionType[]>([]);
  const [tab, setTab] = useState<'locations' | 'connections'>('locations');
  const [showNewLoc, setShowNewLoc] = useState(false);
  const [showNewConn, setShowNewConn] = useState(false);
  const [msg, setMsg] = useState('');

  // Location form
  const [locName, setLocName] = useState('');
  const [locLat, setLocLat] = useState('');
  const [locLng, setLocLng] = useState('');
  const [locCov, setLocCov] = useState('5');
  const [locHand, setLocHand] = useState('15');
  const [locCollection, setLocCollection] = useState(false);
  const [locTransfer, setLocTransfer] = useState(false);
  const [locLab, setLocLab] = useState(false);

  // Connection form
  const [connFrom, setConnFrom] = useState('');
  const [connTo, setConnTo] = useState('');
  const [connMinutes, setConnMinutes] = useState('30');
  const [connCost, setConnCost] = useState('1');
  const [connCooled, setConnCooled] = useState(false);

  useEffect(() => {
    if (bootstrap) {
      setLocations(bootstrap.locations || []);
      setConnections(bootstrap.connections || []);
    }
  }, [bootstrap]);

  async function handleCreateLoc() {
    try {
      await createLocation({
        name: locName,
        coordinate: { latitude: parseFloat(locLat), longitude: parseFloat(locLng) },
        coverageKm: parseFloat(locCov),
        handlingMinutes: parseFloat(locHand),
        active: true,
        functions: { collection: locCollection, transfer: locTransfer, laboratory: locLab },
      });
      setMsg('Location created');
      await refreshBootstrap();
      setShowNewLoc(false);
    } catch (e: unknown) { setMsg(e instanceof Error ? e.message : 'Error'); }
  }

  async function handleToggleLoc(locId: string, active: boolean) {
    try {
      await setLocationStatus(locId, !active);
      await refreshBootstrap();
    } catch (e: unknown) { setMsg(e instanceof Error ? e.message : 'Error'); }
  }

  async function handleToggleFunc(locId: string, func: string, active: boolean) {
    try {
      await setLocationFunctionStatus(locId, func, !active);
      await refreshBootstrap();
    } catch (e: unknown) { setMsg(e instanceof Error ? e.message : 'Error'); }
  }

  async function handleCreateConn() {
    try {
      await createConnection({
        fromLocationId: connFrom,
        toLocationId: connTo,
        travelMinutes: parseFloat(connMinutes),
        costUnits: parseFloat(connCost),
        cooled: connCooled,
        active: true,
      });
      setMsg('Connection created');
      await refreshBootstrap();
      setShowNewConn(false);
    } catch (e: unknown) { setMsg(e instanceof Error ? e.message : 'Error'); }
  }

  async function handleToggleConn(connId: string, active: boolean) {
    try {
      await setConnectionStatus(connId, !active);
      await refreshBootstrap();
