{"command": "create", "path": "/workspace/frontend/src/pages/UserView.tsx", "file_text": "import { useState } from 'react';
import { createUser, updateUserAccess } from '../api/client';
import { useAuth } from '../context/AuthContext';
import type { AuthUser } from '../types';

export default function UserView() {
  const { bootstrap, refreshBootstrap } = useAuth();
  const [showNew, setShowNew] = useState(false);
  const [editUser, setEditUser] = useState<AuthUser | null>(null);
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [email, setEmail] = useState('');
  const [fullName, setFullName] = useState('');
  const [phone, setPhone] = useState('');
  const [roles, setRoles] = useState<string[]>([]);
  const [qualifications, setQualifications] = useState<string[]>([]);
  const [assignedLocId, setAssignedLocId] = useState('');
  const [msg, setMsg] = useState('');

  const users = bootstrap?.users || [];
  const locations = bootstrap?.locations || [];

  function toggleRole(r: string) {
    setRoles(prev => prev.includes(r) ? prev.filter(x => x !== r) : [...prev, r]);
  }

  function resetForm() {
    setUsername(''); setPassword(''); setEmail(''); setFullName(''); setPhone(''); setRoles([]);
    setQualifications([]); setAssignedLocId(''); setShowNew(false); setEditUser(null);
  }

  async function handleCreate() {
    try {
      await createUser({
        username, initialPassword: password, email, fullName, phone, roles,
        qualifications, active: true, assignedLocationId: assignedLocId || undefined,
      });
      setMsg('User created');
      await refreshBootstrap();
      resetForm();
    } catch (e: unknown) { setMsg(e instanceof Error ? e.message : 'Error'); }
  }

  async function handleUpdate() {
    try {
      await updateUserAccess({
        userId: editUser!.userId,
        roles, qualifications, active: true, assignedLocationId: assignedLocId || undefined,
      });
      setMsg('User updated');
      await refreshBootstrap();
      resetForm();
    } catch (e: unknown) { setMsg(e instanceof Error ? e.message : 'Error'); }
  }

  function startEdit(u: AuthUser) {
    setEditUser(u);
    setUsername(u.username);
    setEmail(u.email || '');
    setFullName(u.fullName || '');
    setPhone(u.phone || '');
    setRoles(u.roles || []);
    setQualifications(u.qualifications || []);
    setAssignedLocId(u.assignedLocationId || '');
  }

  return (
    <div>
      <div className="page-header">
        <h1 className="page-title">Users</h1>
        <button className="btn btn-primary" onClick={() => { resetForm(); setShowNew(true); }}>New User</button>
      </div>

      {msg && <div className="card mb-2" style={{ padding: '0.5rem 1rem' }}>{msg}</div>}

      {(showNew || editUser) && (
        <div className="card mb-2" style={{ padding: '1rem' }}>
          <h3 className="mb-2">{showNew ? 'New User' : `Edit ${editUser?.username}`}</h3>
          <div className="grid grid-3">
            <div className="form-group"><label>Username</label><input value={username} onChange={e => setUsername(e.target.value)} disabled={!!editUser} /></div>
            <div className="form-group"><label>{showNew ? 'Password' : 'New Password (leave blank)'}</label><input type="password" value={password} onChange={e => setPassword(e.target.value)} /></div>
            <div className="form-group"><label>Email</label><input value={email} onChange={e => setEmail(e.target.value)} /></div>
            <div className="form-group"><label>Full Name</label><input value={fullName} onChange={e => setFullName(e.target.value)} /></div>
            <div className="form-group"><label>Phone</label><input value={phone} onChange={e => setPhone(e.target.value)} /></div>
            <div className="form-group">
              <label>Assigned Location</label>
              <select value={assignedLocId} onChange={e => setAssignedLocId(e.target.value)}>
                <option value="">— None —</option>
                {locations.map(l => <option key={l.locationId || l.id} value={l.locationId || l.id}>{l.name}</option>)}
              </select>
            </div>
          </div>

          <div className="mt-2">
            <label className="text-sm font-bold">Roles</label>
            <div className="flex gap-2 mt-1" style={{ flexWrap: 'wrap' }}>
              {['administrator', 'dispatcher', 'requester', 'collection_professional', 'delivery_partner', 'node_handler', 'laboratory_team'].map(r => (
                <label key={r} className="text-sm">
                  <input type="checkbox" checked={roles.includes(r)} onChange={() => toggleRole(r)} /> {r.replace(/_/g, ' ')}
                </label>
              ))}
            </div>
          </div>

          <div className="mt-2">
            <label className="text-sm font-bold">Qualifications (comma-separated)</label>
            <input
              className="form-group"
              style={{ width: '100%', marginTop: '0.25rem' }}
              value={qualifications.join(', ')}
              onChange={e => setQualifications(e.target.value.split(',').map(s => s.trim()).filter(Boolean))}
            />
          </div>

          <div className="flex gap-1 mt-2">
            {showNew && <button className="btn btn-primary" onClick={handleCreate}>Create</button>}
            {editUser && <button className="btn btn-primary" onClick={handleUpdate}>Update</button>}
            <button className="btn" onClick={resetForm}>Cancel</button>
          </div>
        </div>
      )}

      <div className="card" style={{ padding: '1rem' }}>
        <div style={{ maxHeight: '500px', overflow: 'auto' }}>
          <table className="table">
            <thead>
              <tr><th>Username</th><th>Name</th><th>Roles</th><th>Location</th><th>Active</th><th></th></tr>
            </thead>
            <tbody>
              {users.map((u) => (
                <tr key={u.userId}>
                  <td className="font-bold">{u.username}</td>
                  <td>{u.fullName || '—'}</td>
                  <td className="text-sm">{(u.roles || []).map(r => r.replace(/_/g, ' ')).join(', ')}</td>
                  <td className="text-sm">{u.assignedLocationId?.slice(0, 8) || '—'}</td>
                  <td><span className={`badge ${u.active ? 'badge-complete' : 'badge-exception'}`}>{u.active ? 'Active' : 'Inactive'}</span></td>
                  <td><button className="btn btn-sm" onClick={() => startEdit(u)}>Edit</button></td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}"}

{"command": "create", "path": "/workspace/frontend/src/pages/MapView.tsx", "file_text": "import { useEffect, useRef, useState } from 'react';
import { readOperationsState } from '../api/client';
import type { OperationsState, Location, SampleState, Coordinates } from '../types';

export default function MapView() {
  const mapContainer = useRef<HTMLDivElement>(null);
  const mapRef = useRef<unknown>(null);
  const [state, setState] = useState<OperationsState | null>(null);

  useEffect(() => {
    readOperationsState().then(res => setState(res.data)).catch(() => {});
  }, []);

  useEffect(() => {
    if (!mapContainer.current) return;
    let mounted = true;

    async function init() {
      try {
        const maplibregl = await import('maplibre-gl');
        if (!mounted || !mapContainer.current) return;

        const map = new maplibregl.default.Map({
          container: mapContainer.current,
          style: {
            version: 8,
            sources: {},
            layers: [],
          },
          center: [0, 0],
          zoom: 1,
        });

        map.addControl(new maplibregl.default.NavigationControl(), 'top-right');
        mapRef.current = map;
      } catch {
        // Render simple canvas fallback
        renderFallback();
      }
    }

    function renderFallback() {
      if (!mapContainer.current) return;
      const canvas = document.createElement('canvas');
      canvas.width = mapContainer.current.clientWidth;
      canvas.height = 400;
      canvas.style.width = '100%';
      canvas.style.height = '400px';
      canvas.style.borderRadius = '6px';
      mapContainer.current.innerHTML = '';
      mapContainer.current.appendChild(canvas);

      const ctx = canvas.getContext('2d');
      if (!ctx) return;
      ctx.fillStyle = '#f0f4f8';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = '#64748b';
      ctx.font = '14px sans-serif';
      ctx.fillText('Map — MapLibre GL JS (PMTiles or OpenStreetMap raster)', 20, 30);

      // Draw sample dots
      if (state?.samples) {
        const lngs = state.samples.map(s => s.origin.longitude);
        const lats = state.samples.map(s => s.origin.latitude);
        const minLng = Math.min(...lngs, -180);
        const maxLng = Math.max(...lngs, 180);
        const minLat = Math.min(...lats, -90);
        const maxLat = Math.max(...lats, 90);
        const padLng = (maxLng - minLng) * 0.1 || 1;
        const padLat = (maxLat - minLat) * 0.1 || 1;

        state.samples.forEach(s => {
          const x = ((s.origin.longitude - minLng + padLng) / (maxLng - minLng + 2 * padLng)) * canvas.width;
          const y = canvas.height - ((s.origin.latitude - minLat + padLat) / (maxLat - minLat + 2 * padLat)) * canvas.height;
          ctx.fillStyle = s.exception ? '#ef4444' : '#2563eb';
          ctx.beginPath();
          ctx.arc(x, y, 6, 0, Math.PI * 2);
          ctx.fill();
          ctx.fillStyle = '#1e293b';
          ctx.font = '10px sans-serif';
          ctx.fillText(s.sampleId.slice(0, 8), x + 8, y - 4);
        });
      }

      // Draw location dots
      if (state?.locations) {
        state.locations.forEach(loc => {
          if (!loc.coordinate) return;
          const lngs = state.locations!.map(l => l.coordinate!.longitude);
          const lats = state.locations!.map(l => l.coordinate!.latitude);
          const minLng = Math.min(...lngs, -180);
          const maxLng = Math.max(...lngs, 180);
          const minLat = Math.min(...lats, -90);
          const maxLat = Math.max(...lats, 90);
          const padLng = (maxLng - minLng) * 0.1 || 1;
          const padLat = (maxLat - minLat) * 0.1 || 1;

          const x = ((loc.coordinate.longitude - minLng + padLng) / (maxLng - minLng + 2 * padLng)) * canvas.width;
          const y = canvas.height - ((loc.coordinate.latitude - minLat + padLat) / (maxLat - minLat + 2 * padLat)) * canvas.height;
          ctx.fillStyle = loc.active ? '#16a34a' : '#94a3b8';
          ctx.beginPath();
          ctx.arc(x, y, 8, 0, Math.PI * 2);
          ctx.fill();
          ctx.fillStyle = '#1e293b';
          ctx.font = 'bold 10px sans-serif';
          ctx.fillText(loc.name.slice(0, 12), x + 10, y);
        });
      }
    }

    init();
    return () => { mounted = false; };
  }, [state]);

  return (
    <div>
      <div className="page-header">
        <h1 className="page-title">Live Map</h1>
        <button className="btn" onClick={() => readOperationsState().then(r => setState(r.data))}>Refresh</button>
      </div>

      <div ref={mapContainer} className="map-container" />

      <div className="grid grid-3 mt-2">
        <div className="card" style={{ padding: '1rem' }}>
          <div className="font-bold">Samples ({state?.samples?.length || 0})</div>
          <ul className="timeline mt-1">
            {state?.samples?.slice(0, 5).map(s => (
              <li key={s.sampleId}>
                <span>{s.sampleId.slice(0, 8)}... <span className={`badge ${s.locationStale ? 'badge-stale' : 'badge-active'}`}>{s.locationStale ? 'STALE' : 'fresh'}</span></span>
                <span className="text-sm text-secondary">{s.state?.status as string || s.status}</span>
              </li>
            ))}
          </ul>
        </div>

        <div className="card" style={{ padding: '1rem' }}>
          <div className="font-bold">Locations ({state?.locations?.length || 0})</div>
          <ul className="timeline mt-1">
            {state?.locations?.slice(0, 5).map(loc => (
              <li key={loc.locationId || loc.id}>
                <span>{loc.name}</span>
                <span className={`badge ${loc.active ? 'badge-complete' : 'badge-exception'}`}>{loc.active ? 'active' : 'inactive'}</span>
              </li>
            ))}
          </ul>
        </div>

        <div className="card" style={{ padding: '1rem' }}>
          <div className="font-bold">Handoffs ({state?.handoffs?.length || 0})</div>
          <ul className="timeline mt-1">
            {state?.handoffs?.slice(0, 5).map(h => (
              <li key={h.handoffId}>
                <span>{h.handoffId.slice(0, 8)}...</span>
                <span className={`badge ${h.status === 'pending_sender' || h.status === 'pending_receiver' ? 'badge-pending' : 'badge-complete'}`}>{h.status}</span>
              </li>
            ))}
          </ul>
        </div>
      </div>
    </div>
  );
}"}

