}", "new_str": "// spaFileServer wraps a FileServer to fall back to index.html for SPA routing.
type spaHandler struct {
	root http.FileSystem
	fs   http.Handler
}

func (h *spaHandler) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	path := r.URL.Path
	f, err := h.root.Open(path)
	if err != nil {
		// Fall back to index.html
		r.URL.Path = "/"
		h.fs.ServeHTTP(w, r)
		return
	}
	f.Close()
	h.fs.ServeHTTP(w, r)
}

func spaFileServer(root http.FileSystem) http.Handler {
	return &spaHandler{root: root, fs: http.FileServer(root)}
}

// Logging
func init() {
	log.SetFlags(log.LstdFlags | log.Lmicroseconds)
}"}

